+const assert = require('node:assert/strict');
+const fs = require('node:fs');
+const vm = require('node:vm');
+
+function localDateString(date) {
+  return [
+    date.getFullYear(),
+    String(date.getMonth() + 1).padStart(2, '0'),
+    String(date.getDate()).padStart(2, '0'),
+  ].join('-');
+}
+
+function loadSignupForm(dateOfBirth) {
+  let submit;
+  const inputs = {
+    name: { id: 'name', value: 'Ada Lovelace', setAttribute() {} },
+    email: { id: 'email', value: 'ada@example.com', setAttribute() {} },
+    password: { id: 'password', value: 'password123', setAttribute() {} },
+    dateOfBirth: { id: 'date-of-birth', value: dateOfBirth, setAttribute() {} },
+  };
+  const errors = Object.fromEntries(
+    Object.values(inputs).map((input) => [`${input.id}-error`, { hidden: true, textContent: '' }]),
+  );
+  const form = {
+    elements: inputs,
+    addEventListener(type, listener) {
+      if (type === 'submit') submit = listener;
+    },
+  };
+  const document = {
+    getElementById(id) {
+      if (id === 'signup-form') return form;
+      return Object.values(inputs).find((input) => input.id === id) || errors[id];
+    },
+  };
+
+  vm.runInNewContext(fs.readFileSync('signup.js', 'utf8'), { Date, document });
+  return { errors, submit };
+}
+
+function submitDateOfBirth(dateOfBirth) {
+  const { errors, submit } = loadSignupForm(dateOfBirth);
+  let prevented = false;
+  submit({ preventDefault() { prevented = true; } });
+  return { error: errors['date-of-birth-error'].textContent, prevented };
+}
+
+const cutoff = new Date();
+cutoff.setFullYear(cutoff.getFullYear() - 13);
+
